const { chromium } = require('playwright-core');
const path = require('path');

(async () => {
  const executablePath = path.join(
    process.env.USERPROFILE,
    'AppData/Local/ms-playwright/chromium-1228/chrome-win/chrome.exe'
  );
  const browser = await chromium.launch({ executablePath, headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  page.on('console', (msg) => console.log('CONSOLE:', msg.type(), msg.text()));
  page.on('pageerror', (err) => console.log('PAGEERROR:', err.message));

  await page.goto('http://localhost:8791/index.html');
  await page.screenshot({ path: '/tmp/monster-test/01-idle.png' });
  console.log('idle walker count:', await page.locator('.monster-walker').count());

  await page.keyboard.press('Alt+a');
  await page.waitForSelector('.monster-walker', { timeout: 2000 });
  console.log('after Alt+A walker count:', await page.locator('.monster-walker').count());
  await page.screenshot({ path: '/tmp/monster-test/02-walking-start.png' });

  // press again while walking - should not spawn a second one
  await page.keyboard.press('Alt+a');
  await page.waitForTimeout(300);
  console.log('walker count after second Alt+A while walking:', await page.locator('.monster-walker').count());

  await page.waitForTimeout(1500);
  await page.screenshot({ path: '/tmp/monster-test/03-walking-mid.png' });
  const box = await page.locator('.monster-walker').boundingBox();
  console.log('mid-crossing bounding box:', JSON.stringify(box));

  // wait for the crossing to finish (duration depends on viewport width / stride)
  await page.waitForSelector('.monster-walker', { state: 'detached', timeout: 15000 });
  console.log('walker removed after animation finished: true');
  await page.screenshot({ path: '/tmp/monster-test/04-after.png' });

  // confirm it can be triggered again after finishing
  await page.keyboard.press('Alt+a');
  await page.waitForSelector('.monster-walker', { timeout: 2000 });
  console.log('re-triggerable after finishing:', await page.locator('.monster-walker').count());

  await browser.close();
})().catch((e) => {
  console.error('TEST FAILED:', e);
  process.exit(1);
});

